#!/usr/bin/env python3
import os
import sys
import shlex
import subprocess

HELP_TEXT = '''pier 0.1.6
Benjamin Scholtz, Isak Johansson
A simple script management CLI

USAGE:
    executable [FLAGS] [OPTIONS] <alias> [args]...
    executable [FLAGS] [OPTIONS] <SUBCOMMAND>

FLAGS:
    -h, --help       
            Prints help information

    -V, --version    
            Prints version information

    -v, --verbose    
            The level of verbosity


OPTIONS:
    -c, --config-file <path>    
            Sets a custom config file.

            DEFAULT PATH is otherwise determined in this order:

            - $PIER_CONFIG_PATH (environment variable if set)

            - pier.toml (in the current directory)

            - $XDG_CONFIG_HOME/pier/config.toml

            - $XDG_CONFIG_HOME/pier/config

            - $XDG_CONFIG_HOME/pier.toml

            - $HOME/.pier.toml

            - $HOME/.pier
             [env: PIER_CONFIG_PATH=]

ARGS:
    <alias>      
            The alias or name for the script.

    <args>...    
            The positional arguments to send to script.


SUBCOMMANDS:
    add            Add a new script to config.
    config-init    alias: init - Add a config file.
    copy           alias: cp - Copy existing alias to the new one
    edit           Edit a script matching alias.
    help           Prints this message or the help of the given subcommand(s)
    list           alias: ls - List scripts
    move           alias: mv, rename - Move/rename existing alias to the new one
    remove         alias: rm - Remove a script matching alias.
    run            Run a script matching alias.
    show           Show a script matching alias.
'''

DEFAULT_SAMPLE = """[scripts.hello-pier]
command = 'echo Hello, Pier!'
description = 'This is an example command.'

[default]
"""

def resolve_config_path(explicit=None):
    if explicit:
        return explicit
    env = os.environ
    if env.get('PIER_CONFIG_PATH'):
        return env.get('PIER_CONFIG_PATH')
    if os.path.exists('pier.toml'):
        return os.path.abspath('pier.toml')
    xdg = env.get('XDG_CONFIG_HOME')
    if xdg:
        # check several options
        candidates = [os.path.join(xdg,'pier','config.toml'),
                      os.path.join(xdg,'pier','config'),
                      os.path.join(xdg,'pier.toml')]
        for c in candidates:
            if os.path.exists(c):
                return c
        # return first candidate for creation
        return candidates[0]
    home = env.get('HOME')
    if home:
        c1 = os.path.join(home,'.pier.toml')
        c2 = os.path.join(home,'.pier')
        if os.path.exists(c1):
            return c1
        if os.path.exists(c2):
            return c2
        return c1
    return None

def ensure_config_exists(path):
    try:
        d = os.path.dirname(path)
        if d and not os.path.exists(d):
            os.makedirs(d, exist_ok=True)
        # if file doesn't exist, create with sample
        if not os.path.exists(path):
            with open(path,'w') as f:
                f.write(DEFAULT_SAMPLE)
        return True, None
    except Exception as e:
        return False, str(e)

def parse_toml_simple(path):
    scripts = {}
    if not os.path.exists(path):
        return scripts
    cur = None
    with open(path,'r') as f:
        for line in f:
            line=line.strip()
            if not line or line.startswith('#'):
                continue
            if line.startswith('[') and line.endswith(']'):
                section = line[1:-1].strip()
                if section.startswith('scripts.'):
                    cur = section.split('scripts.',1)[1]
                    scripts[cur]={}
                else:
                    cur=None
                continue
            if cur:
                if '=' in line:
                    k,v = line.split('=',1)
                    k=k.strip()
                    v=v.strip().strip('\"').strip("'")
                    scripts[cur][k]=v
    return scripts

def write_toml_simple(path, scripts):
    # overwrite file with scripts and default header
    with open(path,'w') as f:
        for name, data in scripts.items():
            f.write(f"[scripts.{name}]\n")
            for k,v in data.items():
                f.write(f"{k} = '{v}'\n")
            f.write("\n")
        f.write("[default]\n")

def print_list(scripts):
    # mimic original table formatting
    border = '≖'*93
    print(border)
    print('⋮ Alias      ⋮ Tags ⋮ Command           ⋮ Description                 ⋮')
    print(border)
    for name,data in scripts.items():
        cmd = data.get('command','')
        desc = data.get('description','')
        print(f"⋮ {name.ljust(10)[:10]} ⋮ {''.ljust(4)} ⋮ {cmd.ljust(17)[:17]} ⋮ {desc.ljust(25)[:25]} ⋮")
    print(border)

def cmd_config_init(args):
    # Determine path
    path = resolve_config_path()
    if not path:
        print('error: Failed to create directory. No such file or directory (os error 2)')
        return 1
    ok,err = ensure_config_exists(path)
    if not ok:
        # mimic earlier error message
        print(f'error: Failed to create directory. {err}')
        return 1
    # On success print "Added hello-pier"
    print('Added hello-pier')
    return 0

def cmd_list(args):
    # check for --config-file
    cfg = None
    if '--config-file' in args:
        i = args.index('--config-file')
        if i+1 < len(args):
            cfg = args[i+1]
    path = resolve_config_path(cfg)
    if not path or not os.path.exists(path):
        print('error: No default config file found. See help for more info.')
        return 1
    scripts = parse_toml_simple(path)
    if not scripts:
        print('No scripts found.')
        return 0
    print_list(scripts)
    return 0

def cmd_add(args):
    if not args:
        print('error: Missing alias')
        return 1
    alias = args[0]
    # parse options
    cmd = None; desc = ''
    cfg = None
    i=1
    while i < len(args):
        a = args[i]
        if a in ('--command','-c'):
            i+=1
            if i<len(args):
                cmd = args[i]
        elif a == '--description':
            i+=1
            if i<len(args):
                desc = args[i]
        elif a == '--config-file':
            i+=1
            if i<len(args):
                cfg = args[i]
        i+=1
    if not cmd:
        print('error: Missing --command')
        return 1
    path = resolve_config_path(cfg)
    if not path:
        print('error: No default config file found. See help for more info.')
        return 1
    # ensure exists
    ok,err = ensure_config_exists(path)
    if not ok:
        print(f'error: Failed to create directory. {err}')
        return 1
    scripts = parse_toml_simple(path)
    scripts[alias]={'command':cmd,'description':desc}
    write_toml_simple(path,scripts)
    print(f"Added {alias}")
    return 0

def cmd_run(args):
    if not args:
        print('error: Missing alias')
        return 1
    alias = args[0]
    rest = args[1:]
    # check config
    cfg=None
    if '--config-file' in args:
        i = args.index('--config-file')
        if i+1 < len(args):
            cfg = args[i+1]
    path = resolve_config_path(cfg)
    if not path or not os.path.exists(path):
        print('error: No default config file found. See help for more info.')
        return 1
    scripts = parse_toml_simple(path)
    if alias not in scripts:
        print(f'error: No script matching alias "{alias}" found.')
        return 1
    cmd = scripts[alias].get('command','')
    # append args
    if rest:
        cmd = cmd + ' ' + ' '.join(shlex.quote(a) for a in rest)
    try:
        res = subprocess.run(cmd, shell=True)
        return res.returncode
    except Exception as e:
        print(f'error: Failed to run script: {e}')
        return 1

def cmd_remove(args):
    if not args:
        print('error: Missing alias')
        return 1
    alias = args[0]
    cfg=None
    path = resolve_config_path(cfg)
    if not path or not os.path.exists(path):
        print('error: No default config file found. See help for more info.')
        return 1
    scripts = parse_toml_simple(path)
    if alias in scripts:
        scripts.pop(alias)
        write_toml_simple(path,scripts)
        print(f'Removed {alias}')
        return 0
    else:
        print(f'error: No script matching alias "{alias}" found.')
        return 1

def cmd_show(args):
    if not args:
        print('error: Missing alias')
        return 1
    alias = args[0]
    path = resolve_config_path()
    if not path or not os.path.exists(path):
        print('error: No default config file found. See help for more info.')
        return 1
    scripts = parse_toml_simple(path)
    if alias not in scripts:
        print(f'error: No script matching alias "{alias}" found.')
        return 1
    s = scripts[alias]
    print(f"alias: {alias}")
    print(f"command: {s.get('command','')}")
    if s.get('description'):
        print(f"description: {s.get('description')}")
    return 0

def cmd_copy(args):
    if len(args)<2:
        print('error: Missing args')
        return 1
    src, dst = args[0], args[1]
    path = resolve_config_path()
    if not path or not os.path.exists(path):
        print('error: No default config file found. See help for more info.')
        return 1
    scripts = parse_toml_simple(path)
    if src not in scripts:
        print(f'error: No script matching alias "{src}" found.')
        return 1
    scripts[dst]=scripts[src].copy()
    write_toml_simple(path,scripts)
    print(f'Added {dst}')
    return 0

def cmd_move(args):
    if len(args)<2:
        print('error: Missing args')
        return 1
    src, dst = args[0], args[1]
    path = resolve_config_path()
    if not path or not os.path.exists(path):
        print('error: No default config file found. See help for more info.')
        return 1
    scripts = parse_toml_simple(path)
    if src not in scripts:
        print(f'error: No script matching alias "{src}" found.')
        return 1
    scripts[dst]=scripts.pop(src)
    write_toml_simple(path,scripts)
    print(f'Moved {src} -> {dst}')
    return 0


def main():
    argv = sys.argv[1:]
    if not argv:
        print(HELP_TEXT)
        return 0
    # global flags
    if '--help' in argv or '-h' in argv:
        print(HELP_TEXT)
        return 0
    if '--version' in argv or '-V' in argv:
        print('pier 0.1.6')
        return 0
    # handle subcommands
    cmd = argv[0]
    if cmd in ('config-init','init'):
        return cmd_config_init(argv[1:])
    if cmd in ('list','ls'):
        return cmd_list(argv[1:])
    if cmd == 'add':
        return cmd_add(argv[1:])
    if cmd == 'run':
        return cmd_run(argv[1:])
    if cmd in ('remove','rm'):
        return cmd_remove(argv[1:])
    if cmd == 'show':
        return cmd_show(argv[1:])
    if cmd in ('copy','cp'):
        return cmd_copy(argv[1:])
    if cmd in ('move','mv','rename'):
        return cmd_move(argv[1:])
    if cmd == 'help':
        print(HELP_TEXT)
        return 0
    # otherwise treat first arg as alias to run
    # fallback: run alias
    return cmd_run(argv)

if __name__=='__main__':
    rc = main()
    sys.exit(rc)
